  -ms-transform: rotate(0);
  transform: rotate(0);
  position: absolute;
  z-index: 1;
  top: 50% !important;
  left: 50% !important;
  -webkit-transform: translate(-50%, -50%) rotate(0deg);
  -ms-transform: translate(-50%, -50%) rotate(0deg);
  transform: translate(-50%, -50%) rotate(0deg);
  transform-origin: center center;
  width: auto;
  height: auto;
  font-size: 15px;
